let socketOnDrain;
const request = {
  async cancel(status = Cr.NS_ERROR_ABORT) {
    if (requestCancelled) {
      return;
    }
    requestCancelled = true;
    client.close(true);
    // Unblock a message upload waiting for the socket buffer to drain.
    socketOnDrain?.();
    await notifyStop(status);
  },
};

listener?.onSendStart(request);
